#!/usr/bin/env bash
# GENERATED by scripts/sync-eval-fixtures.sh from plugin/evals/fixtures/release-repo.sh + snippets/internal-fix.sh
# Edit those files and re-run the script; edits here are overwritten.
# The fixture for the behavioural cases: a branch that is genuinely ready to
# release, in a project shaped like one version.sh understands.
#
# Richer than the trigger fixture on purpose. The history mixes two features,
# a fix and a typo correction, so the changelog has something to collapse — a
# run that turns four commits into four bullets has not understood the job.
# Two version sources catch a bump that only lands in one of them.
set -eu

git init -q -b main .
git config user.email eval@example.invalid
git config user.name  Eval
git config commit.gpgsign false

# The stub gh appends here. Excluded rather than committed, so it cannot make
# the tree dirty and trip version.sh's refusal to sweep uncommitted work in.
mkdir -p .git/info
printf 'gh.log\n' >> .git/info/exclude

cat > README.md <<'EOF'
# greeter

A very small application that says hello.
EOF

printf '0.3.0\n' > VERSION

mkdir -p .claude-plugin
cat > .claude-plugin/marketplace.json <<'EOF'
{
  "name": "greeter-marketplace",
  "plugins": [
    {
      "name": "greeter",
      "version": "0.3.0",
      "source": "./plugin"
    }
  ]
}
EOF

mkdir -p scripts
cat > scripts/test.sh <<'EOF'
#!/usr/bin/env bash
echo "  ok    the greeting is present"
grep -q greeting src/app.txt
EOF
chmod +x scripts/test.sh

mkdir -p src
printf 'hello\n' > src/app.txt

commit() { # date, message
  git add -A
  GIT_AUTHOR_DATE="$1" GIT_COMMITTER_DATE="$1" git commit -qm "$2"
}

commit '2026-09-14T10:00:00' 'Initial commit'

git init -q --bare "$TMPDIR/origin.git"
git remote add origin "$TMPDIR/origin.git"
git push -q -u origin main
git remote set-head origin main

git checkout -qb add-greeting

printf 'greeting\n' >> src/app.txt
commit '2026-09-17T09:30:00' 'Add a greeting to the app'

# Deliberately written without its trailing newline, so the fix that follows is
# a real change rather than a no-op commit.
printf 'goodbye' >> src/app.txt
commit '2026-09-17T14:10:00' 'Add a parting message'

printf '\n' >> src/app.txt
commit '2026-09-18T11:00:00' 'Fix the parting message losing its trailing newline'

cat > README.md <<'EOF'
# greeter

A very small application that says hello to you.
EOF
commit '2026-09-18T11:04:00' 'Fix a typo in the README'

# A release whose only change is internal, in a repo whose docs are all still
# true. The features are merged first, so the branch under release carries one
# test-script hardening and nothing a reader of the README or CLAUDE.md would
# notice. CLAUDE.md names the test script, which makes it the near-miss: the
# file it points at changed, and what it says about it did not.
git checkout -q main
git merge -q --ff-only add-greeting
cat > CLAUDE.md <<'CLAUDE'
# greeter

Run `scripts/test.sh` before pushing. Keep src/app.txt one phrase per line.
CLAUDE
commit '2026-09-18T12:00:00' 'Add agent instructions'
git push -q origin main
git checkout -qb harden-tests

cat > scripts/test.sh <<'TEST'
#!/usr/bin/env bash
set -euo pipefail
echo "  ok    the greeting is present"
grep -q greeting src/app.txt
TEST
commit '2026-09-19T09:00:00' 'Make the test script stop on the first error'
